/// The wire error codes whose document is about one OBJECT, and so names the key the request
/// addressed — and, when the request named one, the version it addressed.
///
/// Each states a condition of the address the request named and of nothing else: the key
/// holds no current object ([`crate::state::NO_SUCH_KEY_CODE`]), or the bucket holds no such
/// version of it ([`crate::state::NO_SUCH_VERSION_CODE`]). A client that fans one operation
/// out over many keys reads which one failed from there, and an SDK error object surfaces it
/// as `Key`.
///
/// Source: the elements S3's own error document carries for these conditions (Amazon S3 API
/// Reference, *Error responses*, whose `<Error>` document is `Code`, `Message`, the
/// condition's own contextual elements, `RequestId` and `HostId`). It cannot come from the
/// model, for the same reason [`BUCKET_SCOPED_ERROR_CODES`] cannot: every error shape in
/// `com.amazonaws.s3` declares no members at all. The name is therefore written from the
/// request's own address ([`crate::state::addressed_bucket::addressed_object`]), which is
/// what makes the rule hold for every operation that answers one of these codes rather than
/// for the handlers that spell it out.
pub const OBJECT_SCOPED_ERROR_CODES: &[&str] = &[
    crate::state::NO_SUCH_KEY_CODE,
    crate::state::NO_SUCH_VERSION_CODE,
];

/// Whether an error document carrying `code` is about the object the request addressed — see
/// [`OBJECT_SCOPED_ERROR_CODES`].
pub fn names_its_object(code: &str) -> bool {
    OBJECT_SCOPED_ERROR_CODES.contains(&code)
}

/// The resource a refusal is ABOUT, and therefore which member of the error document names
/// it.
///
/// S3's error document for a resource-scoped refusal is
/// `<Error><Code/><Message/><resource-naming member/><RequestId/><HostId/></Error>`: the
/// code and the message are the fixed text of the error class, and the naming member is a
/// variable part copied from the request, because the envelope is the only place the refusal
/// says WHICH resource it is about. No error shape in this service's model declares such a
/// member (`smithy_query(query="shape",shape="NoSuchBucket,NoSuchAnnotation",
/// model_path="services/service-com-amazonaws-s3-amazons3/smithy-model/com-amazonaws-s3-amazons3.json")`
/// reports no members at all), and the codes the model does not declare have no shape to
/// carry one either — so the member lives on the error CHANNEL, here, once, rather than in
/// each handler's serializer.
#[derive(Debug, Clone)]
pub enum RefusedResource {
    /// A bucket-scoped refusal, named by `<BucketName>`: the bucket the request addressed.
    Bucket(String),
    /// An annotation-scoped refusal, named by `<AnnotationName>`: the annotation name the
    /// request addressed.
    Annotation(String),
    /// A refusal about one TAG of a tag set, named by `<TagKey>`: the key the request
    /// carried.
    TagKey(String),
    /// A refusal about one OBJECT, named by `<Key>` and — for a refusal about one stored
    /// version — `<VersionId>`: the object the refusal is ABOUT, which is NOT always the
    /// one the request addressed. A copy's SOURCE is the case this exists for; every
    /// other object-scoped refusal is about the addressed object and is named from the
    /// request itself (see [`OBJECT_SCOPED_ERROR_CODES`]).
    Object {
        /// The key, as the request spelled it.
        key: String,
        /// The version the refusal is about, for one that names a version.
        version_id: Option<String>,
    },
    /// A refusal about one ARGUMENT of the request, named by the `<ArgumentName>` /
    /// `<ArgumentValue>` pair: the request field whose value was rejected, and the value it
    /// carried. The two members travel together because either alone says only half of
    /// which argument was refused — see [`Scaffolded::invalid_argument`].
    Argument {
        /// The request field, as the API publishes it (`versionId`, `RetainUntilDate`).
        name: String,
        /// The value that field carried, as the request spelled it.
        value: String,
    },
}

impl RefusedResource {
    /// Write the member — or, for an argument or a versioned object, the PAIR of members —
    /// S3's error document names this resource by, in the order the document carries them in.
    fn serialize_into(&self, s: &mut dyn ShapeSerializer) -> Result<(), SerdeError> {
        match self {
            Self::Bucket(name) => s.write_string(&BUCKET_NAME, name),
            Self::Annotation(name) => s.write_string(&ANNOTATION_NAME, name),
            Self::TagKey(key) => s.write_string(&TAG_KEY, key),
            Self::Object { key, version_id } => {
                s.write_string(&OBJECT_KEY, key)?;
                match version_id.as_deref() {
                    Some(version_id) => s.write_string(&OBJECT_VERSION_ID, version_id),
                    None => Ok(()),
                }
            }
            Self::Argument { name, value } => {
                s.write_string(&ARGUMENT_NAME, name)?;
                s.write_string(&ARGUMENT_VALUE, value)
            }
        }
    }

    /// The name itself, exactly as the request spelled it.
    fn name(&self) -> &str {
        match self {
            Self::Bucket(name)
            | Self::Annotation(name)
            | Self::TagKey(name)
            | Self::Object { key: name, .. }
            | Self::Argument { name, .. } => name.as_str(),
        }
    }
}

/// An operation's error channel: either the synthetic scaffold signal, or one of the
/// operation's own modeled errors.
#[derive(Debug)]
pub enum Scaffolded<E> {
    /// The operation is generated but has no implementation. Renders as HTTP 501.
    NotImplemented(NotImplemented),
    /// A modeled error the operation declares. Renders with the model's own status.
    Modeled(E),
    /// The request was refused as invalid. Renders as HTTP 400 with the error code
    /// `ValidationException`.
    ///
    /// On the JSON and CBOR protocols that is the same status and code the boundary
    /// validator answers with. Two differences are worth knowing, and neither is
    /// specific to this variant — every handler-returned error shares them:
    /// the awsJson families omit the `x-amzn-errortype` header that the boundary
    /// path sets, and the query protocols render a boundary refusal as
    /// `MalformedQueryString` rather than `ValidationException`, so a client
    /// matching on the error code there sees two codes for one logical failure.
    ValidationException(ValidationException),
    /// A rejection whose code the model does not declare, rendered with the code and
    /// status S3 actually sends. See [`Unmodeled`].
    Unmodeled(Unmodeled),
    /// Any of the refusals above, ABOUT a named resource: the refusal is rendered exactly
    /// as it would be on its own, plus the member S3's error document names that resource
    /// by. See [`RefusedResource`] and [`Scaffolded::naming`].
    Naming(Box<Scaffolded<E>>, RefusedResource),
}

impl<E> Scaffolded<E> {
    /// The scaffold signal for `operation`.
    pub fn not_implemented(operation: &str) -> Self {
        Self::NotImplemented(NotImplemented::new(operation))
    }

    /// Refuse the request as invalid, with HTTP 400 `ValidationException`.
    ///
    /// Reach for this when the request is wrong in a way the model cannot express,
    /// so the boundary validator passed it: a value outside a rule the service
    /// enforces but does not model, or a combination of members that cannot hold
    /// together. Answer it INSTEAD of `not_implemented` — a 501 says "nobody has
    /// written this yet", which is a different claim and is counted as one.
    ///
    /// If this service's model declares its own `ValidationException` (or another
    /// client-input error) use THAT: the modeled shape may carry members beyond
    /// `message` — a `reason`, a field list — and a real client reads them. When the
    /// operation already lists it, it is a plain variant on the generated error enum;
    /// `#[operation_error]`'s `extra_errors` is only for widening in a shape the
    /// SERVICE models that this OPERATION does not list.
    pub fn validation(message: impl Into<String>) -> Self {
        Self::ValidationException(ValidationException::new(message))
    }

    /// Refuse the request with an error code this operation's model does not declare.
    ///
    /// Only for a code the emulated service demonstrably sends where the model names
    /// none — S3's bucket subresource operations model no errors at all, yet answer
    /// `NoSuchBucket`, `NoSuchBucketPolicy`, `NoSuchTagSet` and `MalformedPolicy`, and
    /// the object-storage loop answers `BucketNotEmpty`, `InvalidArgument`,
    /// `EntityTooLarge`, `BadDigest`, `ServiceUnavailable` and `InternalError` the same
    /// way. Prefer a modeled variant whenever the model has one for the failure.
    pub fn unmodeled(code: &'static str, status: u16, message: impl Into<String>) -> Self {
        Self::Unmodeled(Unmodeled {
            code,
            status,
            message: message.into(),
        })
    }

    /// This refusal, with the member S3's error document names `resource` by.
    ///
    /// Reach for it wherever a request is refused BECAUSE of the resource it addresses —
    /// the resource, or a configuration of it, not being there, or already being there —
    /// since the envelope is the only place such a refusal says which resource it is
    /// about: a client driving several buckets or annotations through one code path cannot
    /// attribute the failure without it, and an SDK error shape that exposes the member
    /// hands back nothing. The code, the status and the message are untouched.
    ///
    /// Naming a resource twice REPLACES the name rather than writing the member twice.
    pub fn naming(self, resource: RefusedResource) -> Self {
        match self {
            Self::Naming(refusal, _) => Self::Naming(refusal, resource),
            refusal => Self::Naming(Box::new(refusal), resource),
        }
    }

    /// [`Scaffolded::naming`] for the bucket a bucket-scoped refusal is about.
    pub fn naming_bucket(self, bucket: &str) -> Self {
        self.naming(RefusedResource::Bucket(bucket.to_string()))
    }

    /// [`Scaffolded::naming`] for the annotation an annotation-scoped refusal is about.
    pub fn naming_annotation(self, annotation: &str) -> Self {
        self.naming(RefusedResource::Annotation(annotation.to_string()))
    }

    /// [`Scaffolded::naming`] for the OBJECT an object-scoped refusal is about, where that is
    /// not the object the request addressed: a copy's SOURCE, whose key the destination's
    /// address would otherwise be written in place of.
    pub fn naming_object(self, key: &str, version_id: Option<&str>) -> Self {
        self.naming(RefusedResource::Object {
            key: key.to_string(),
            version_id: version_id.map(str::to_string),
        })
    }

    /// The refusal S3 answers a request field carrying a value it cannot accept with:
    /// `InvalidArgument` at [`crate::state::INVALID_ARGUMENT_STATUS`], plus the
    /// `<ArgumentName>` / `<ArgumentValue>` pair naming WHICH field was rejected and what it
    /// carried.
    ///
    /// S3's `InvalidArgument` document carries that pair beside its code and message (Amazon
    /// S3 API Reference, *Error responses*), and an SDK error object surfaces it as
    /// `ArgumentName` / `ArgumentValue`: the message states the RULE the value broke, which
    /// is the same sentence for every value that breaks it, so the pair is the only part of
    /// the refusal that says which argument the caller must change. `argument` is the field
    /// as the API publishes it and `value` is what the request spelled, so neither is
    /// invented here.
    ///
    /// The ONE place that pair is attached, so every field this service refuses a value in
    /// names it the same way.
    pub fn invalid_argument(argument: &str, value: &str, message: impl Into<String>) -> Self {
        Self::unmodeled(
            crate::state::INVALID_ARGUMENT_CODE,
            crate::state::INVALID_ARGUMENT_STATUS,
            message,
        )
        .naming(RefusedResource::Argument {
            name: argument.to_string(),
            value: value.to_string(),
        })
    }

    /// The refusal every operation that takes a `versionId` answers one that is not shaped
    /// like a version id with ([`crate::state::version_id_is_well_formed`] decides it): the
    /// `InvalidArgument` above, naming the `versionId` parameter and echoing the token it
    /// rejected.
    ///
    /// One place, so a malformed id is refused identically wherever it arrives.
    pub fn invalid_version_id(version_id: &str) -> Self {
        Self::invalid_argument(
            crate::state::VERSION_ID_ARGUMENT,
            version_id,
            crate::state::INVALID_VERSION_ID_MESSAGE,
        )
    }

    /// The refusal every WRITE that carries `x-amz-object-lock-retain-until-date` answers a
    /// date that does not end in the future with: the `InvalidArgument` above, naming that
    /// header and echoing the date it rejected as the request spelled it in that header
    /// ([`crate::state::RETAIN_UNTIL_DATE_NOT_IN_FUTURE_MESSAGE`] is the sentence, shared
    /// with the retention write that is refused the same value in its document).
    pub fn retain_until_date_not_in_future(
        spelled: Option<&str>,
        date: Option<&::aws_smithy_types::DateTime>,
    ) -> Self {
        Self::invalid_argument(
            crate::state::OBJECT_LOCK_RETAIN_UNTIL_DATE_HEADER,
            &crate::state::echoed_retain_until_date(spelled, date),
            crate::state::RETAIN_UNTIL_DATE_NOT_IN_FUTURE_MESSAGE,
        )
    }

    /// The refusal S3 answers a tag set that breaks one of the published restrictions with:
    /// the rejection's own wire code and sentence at [`crate::state::TAG_REJECTION_STATUS`],
    /// plus the `<TagKey>` member when the refusal is about one tag's key.
    ///
    /// The ONE place a tag-set rejection becomes a wire refusal, so the several operations
    /// that write a tag set — the two tagging puts and every object write carrying an
    /// `x-amz-tagging` header — cannot disagree about the status, the code or the member
    /// the envelope carries.
    pub fn tag_set(rejection: &crate::state::TagSetRejection) -> Self {
        let refusal = Self::unmodeled(
            rejection.code(),
            crate::state::TAG_REJECTION_STATUS,
            rejection.to_string(),
        );
        match rejection.tag_key() {
            Some(key) => refusal.naming(RefusedResource::TagKey(key.to_string())),
            None => refusal,
        }
    }
}

impl<E: std::fmt::Display> std::fmt::Display for Scaffolded<E> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::NotImplemented(e) => write!(f, "{e}"),
            Self::Modeled(e) => write!(f, "{e}"),
            Self::ValidationException(e) => write!(f, "{e}"),
            Self::Unmodeled(e) => write!(f, "{e}"),
            // The refusal as it reads on its own, plus the resource it is about, so an
            // operator reading a log sees which one it was refused for.
            Self::Naming(refusal, resource) => write!(f, "{refusal} ({})", resource.name()),
        }
    }
}

/// `source()` forwards to the modeled error rather than taking the default `None`, so a
/// modeled error's own `source()` is preserved through the wrapper.
impl<E: std::error::Error + 'static> std::error::Error for Scaffolded<E> {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            Self::NotImplemented(e) => e.source(),
            Self::Modeled(e) => e.source(),
            Self::ValidationException(e) => e.source(),
            Self::Unmodeled(e) => e.source(),
            Self::Naming(refusal, _) => refusal.source(),
        }
    }
}

/// Every error this service puts on the wire is serialized through here, which is what
/// makes "an S3 error document always carries a `<Message>`" one rule rather than one per
/// operation — and the same for the `<BucketName>` a bucket-scoped document names its
/// bucket in.
///
/// The three synthetic channels serialize their own message member unchanged. A MODELED
/// error gets the documented message for its wire code written first — `<Code>` then
/// `<Message>`, the order S3's document uses — followed by whatever members its own shape
/// declares (`InvalidObjectState`'s `StorageClass`, say).
///
/// A refusal that NAMES a resource is serialized as the refusal it wraps and then the
/// member naming that resource, which is the order S3's error document carries them in
/// (`<Message>` then `<BucketName>`) — whichever channel the refusal itself travels on.
///
/// A refusal that names NO resource and whose code is one of
/// [`BUCKET_SCOPED_ERROR_CODES`] is about the bucket the REQUEST addressed, and is named by
/// it ([`crate::state::addressed_bucket`]): those codes state a condition of the addressed
/// bucket, so the envelope's name is the request's own address and the handler has nothing
/// to add.
///
/// [`Scaffolded::naming_bucket`] is what the two cases that default cannot serve must use,
/// and an explicit name always wins, so the member is written exactly once:
///
/// * a refusal about a bucket OTHER than the one addressed — a copy whose SOURCE bucket is
///   not there (`ops/copy_object.rs`, `ops/upload_part_copy.rs`), where the addressed
///   bucket is the destination and exists; and
/// * a refusal answered by a handler that AWAITS, which may be resumed on another worker
///   thread and so cannot read the request-scoped note
///   (`ops/put_bucket_notification_configuration.rs`).
///
/// It is also what names a resource that is not a bucket at all ([`RefusedResource`]).
impl<E: OperationError> SerializableStruct for Scaffolded<E> {
    fn serialize_members(&self, s: &mut dyn ShapeSerializer) -> Result<(), SerdeError> {
        // The request-scoped notes are spent HERE, at the top, whether or not this refusal
        // ends up using them: a refusal that names its own resource, and one whose code is
        // not bucket- or object-scoped, must not leave a note behind for a later response on
        // this thread to name itself by. Taking them first is also what keeps the `Naming`
        // arm's recursive call from writing a second `<BucketName>` — the notes are already
        // gone by the time the wrapped refusal is serialized.
        let addressed = crate::state::addressed_bucket::addressed();
        let addressed_object = crate::state::addressed_bucket::addressed_object();
        match self {
            Self::NotImplemented(e) => e.serialize_members(s)?,
            Self::ValidationException(e) => e.serialize_members(s)?,
            Self::Unmodeled(e) => e.serialize_members(s)?,
            Self::Modeled(e) => {
                if !models_its_own_message(e.variant_schema()) {
                    if let Some(message) = documented_error_message(e.shape_name()) {
                        s.write_string(&DOCUMENTED_MESSAGE, message)?;
                    }
                }
                e.as_serializable().serialize_members(s)?;
            }
            Self::Naming(refusal, resource) => {
                refusal.serialize_members(s)?;
                resource.serialize_into(s)?;
                return Ok(());
            }
        }
        if let Some(bucket) = addressed.filter(|_| names_its_bucket(self.shape_name())) {
            s.write_string(&BUCKET_NAME, bucket.as_str())?;
        }
        if let Some(object) = addressed_object.filter(|_| names_its_object(self.shape_name())) {
            s.write_string(&OBJECT_KEY, object.key.as_str())?;
            if let Some(version_id) = object.version_id.as_deref() {
                s.write_string(&OBJECT_VERSION_ID, version_id)?;
            }
        }
        Ok(())
    }
}

/// Every `OperationError` method delegates to the modeled error, so wrapping an
/// implemented operation's error channel changes NOTHING about how that error is
/// rendered. Only the synthetic variant behaves differently — and it is the one that
/// must answer 501.
impl<E: OperationError> OperationError for Scaffolded<E> {
    /// The wrapper ITSELF is the serializable view, so the `<Message>` the impl above
    /// writes reaches the wire for a modeled error too. Each variant's own members are
    /// serialized by that impl, by delegation.
    fn as_serializable(&self) -> &dyn SerializableStruct {
        self
    }

    fn variant_schema(&self) -> &'static Schema {
        match self {
            Self::NotImplemented(_) => &NOT_IMPLEMENTED_SCHEMA,
            Self::Modeled(e) => e.variant_schema(),
            Self::ValidationException(_) => &VALIDATION_EXCEPTION_SCHEMA,
            Self::Unmodeled(_) => &UNMODELED_SCHEMA,
            // The wrapped refusal's own shape: naming the resource adds a member to the
            // document, it does not make the refusal a different error.
            Self::Naming(refusal, _) => refusal.variant_schema(),
        }
    }

    /// The wire error code (`__type` on JSON/CBOR, `<Code>` on XML).
    ///
    /// Keep the literal as it is: changing it changes the wire error code clients match
    /// on. It is intentionally not tied to the Rust variant name.
    fn shape_name(&self) -> &'static str {
        match self {
            Self::NotImplemented(_) => "NotImplemented",
            Self::Modeled(e) => e.shape_name(),
            Self::ValidationException(_) => "ValidationException",
            // The documented wire code this failure carries, not a Rust variant name.
            Self::Unmodeled(e) => e.code,
            Self::Naming(refusal, _) => refusal.shape_name(),
        }
    }

    /// 501 for the scaffold signal.
    ///
    /// Keep it 501 and not a 5xx server fault: SDK retry classifiers treat those as
    /// retryable, so a client would retry an operation that can never succeed.
    fn http_status(&self) -> u16 {
        match self {
            Self::NotImplemented(_) => 501,
            Self::Modeled(e) => e.http_status(),
            Self::ValidationException(_) => 400,
            Self::Unmodeled(e) => e.status,
            Self::Naming(refusal, _) => refusal.http_status(),
        }
    }

    fn query_error_code(&self) -> Option<&'static str> {
        match self {
            // No awsQuery code: the synthetic shape is not in the model, so there is
            // no `awsQueryError` trait to honour. The 501 + `<Code>NotImplemented`
            // envelope carries the signal on the query protocols too.
            Self::NotImplemented(_) => None,
            Self::Modeled(e) => e.query_error_code(),
            Self::ValidationException(_) => None,
            // Same reason: the synthetic shapes carry no `awsQueryError` trait.
            Self::Unmodeled(_) => None,
            Self::Naming(refusal, _) => refusal.query_error_code(),
        }
    }
}
